+        if (!labels.contains(null)) {
+            // implicit default to exit
+            labels.add(null);
+            blocks.add(exit);
+        }
+        block.add(new ConstantLabelSwitchOp(selector, labels, blocks.stream().map(Block.Builder::reference).toList()));
+        return exit;
+    }
